HEAD_LAY = {
 "B37": "前六批立映射/矩阵/性能账，本批立判据冻结体系——冻结层与前层正交",
 "B38": "前七批立冻结体系，本批立交付物终核与六方移交——交付层与冻结层正交",
 "B39": "前八批立交付冻结，本批立域级总回归——回归层为收官执行主闸",
 "B40": "前九批立总回归，本批立域收官与封账——收官层为域终态",
}

def build(bn, out_lines):
    meta = META[bn]
    items = SKEL[bn]
    idx = int(bn[1:])
    cum = CUM[bn]; rows = ROWS[bn]
    first, last = "F%d" % (4001 + (idx-1)*20), "F%d" % (4020 + (idx-1)*20)
    head = ("# 域 UNX-B1 · 深化册 · UNX-B1-%s（%s–%s · 20 条新深化 · 批收口）\n\n" % (bn, first, last)
        + ("> AI-06 承办｜本册为 %s 批全量深化收口：20/20 条，判据/行数/ID 与 `batches/UNX-B1-%s.md` 骨架逐条同名同判据同 ID，"
           "深化不改判据语义只补六要素与正文｜嫁接源：—（%s，只跟随）｜防重声明：与 m700vfs.rs/storage.rs/fs23_mount.rs/vfsguard.rs 为升级接管分层；%s｜"
           "行数锁定：本批 20 条求和 %s（与骨架 %s–%s 逐条求和零偏离），域累计 %s/240,000%s｜红线声明：本批 20 条均为纯逻辑语义/结构/断言类条目，"
           "不触引导设施红线清单；ktest 断言全部宿主侧可跑，无实机依赖（双轨产线：开发期零 QEMU/零实机写）｜批注：%s。\n\n"
           % (bn, bn, meta[1], HEAD_LAY[bn], format(rows, ","), first, last, format(cum, ","),
              "（满账）" if cum == 240000 else "", meta[2])))
    out_lines.write(head)
    for it in items:
        fid = it["id"]; num = int(fid.split("F")[-1])
        decomp, loc, bound, deps, risk, body = C[num]
        j = it["j"]
        out_lines.write("### %s %s\n" % (fid, it["title"]))
        out_lines.write("- 域/批：B1/%s｜判据：%s｜纯功能行数：%d 行（%s）｜状态：[已深化]\n" % (bn, j, it["rows"], decomp))
        out_lines.write("- **定位**：%s\n" % loc)
        out_lines.write("- **语义边界**：%s\n" % bound)
        out_lines.write("- **依赖与嫁接源**：%s\n" % deps)
        out_lines.write("- **风险与回退**：%s\n" % risk)
        out_lines.write("- 正文：%s\n\n" % body)

for bn in ("B37", "B38", "B39", "B40"):
    path = os.path.join(HERE, "deepen", "B1-%s.md" % bn)
    with io.open(path, "w", encoding="utf-8", newline="\n") as f:
        build(bn, f)
    print("written", path)
